PALETTE_MAP = 0x3FF0
HAND_LIMIT = 10

effectRandom = Random:new()
characters = {Ironclad}

switchWindow(TitleWindow:new())

function TIC()
	doSync()
	window:windowTick()
end

-- in game properties
seed = 0
ascension = 0
player = nil
floor = 1
gold = 0
deck = {}
potions = {Slot,Slot,Slot}
relics = {}
maxEnergy = 3
rubyKeyObtained = false
emeraldKeyObtained = false
sapphireKeyObtained = false
relicPools = {common={},uncommon={},rare={},shop={},boss={}}
shopRemoveCount = 0
oneTimeEvents = {}

-- in act properties
act = nil
stsMap = {}
monsterEncounters = {}
eliteEncounters = {}
bossEncounters = {}
nextMonsterEncounterIndex = 1
nextEliteEncounterIndex = 1
nextBossEncounterIndex = 1
playerPath = {}
currentRoomX = 0
currentRoomY = 0
room = {}
actEvents = {}
commonEvents = {}
roomActionType = nil

function startGame(character,ascensionLevel)
	local random = Random:new(math.floor(tstamp()*2))
	seed = random:randRaw()
	ascension = ascensionLevel or 0
	player = character:new()
	if ascension >= 14 then
		player:decreaseMaxHp(player:getAscensionMaxHPLoss())
	end
	if ascension >= 6 then
		player.hp = math.floor(player.maxHp*0.9+0.5)
	end
	relicPools = generateRelicPools(makeRand(0))
	floor = 0
	gold = 99
	deck = player:getStartDeck()
	if ascension >= 10 then
		table.insert(deck,1,AscendersBane:new())
	end
	relics = player:getStartRelics()
	potions = {Slot,Slot,Slot}
	if ascension >= 11 then
		potions[3] = nil
	end
	maxEnergy = 3
	effects = {}
	pendingEffects = {}
	rubyKeyObtained = false
	emeraldKeyObtained = false
	sapphireKeyObtained = false
	shopRemoveCount = 0
	currentEvent = NeowEvent:new()
	cursorOnTopBar = false
	oneTimeEvents = shallowcopy(getOneTimeEvents())
	startAct(1)
	saveGame()
	switchWindow(GameWindow:new())
end

function startAct(actId)
	act = acts[actId]
	local mapRandom = makeRand(actId)
	stsMap = generateMap(mapRandom,7,15,6)
	monsterEncounters,eliteEncounters,bossEncounters = act:generateEncounters(mapRandom)
	nextMonsterEncounterIndex = 1
	nextEliteEncounterIndex = 1
	nextBossEncounterIndex = 1
	playerPath = {}
	currentRoomX = 0
	currentRoomY = 0
	room = {id=0,x=0,y=0,previous={},next={},type=nil,completed=false}
	for _, nextRoom in ipairs(stsMap[1]) do
		table.insert(room.next,nextRoom)
	end
	roomActionType = 'event'
	resetRewardGenerator()
	resetEventGenerator()
	actEvents = shallowcopy(act.events)
	commonEvents = shallowcopy(getCommonEvents())
	act:playEntryEffect()
end

function completeRoom()
	if room.completed then
		return
	end
	room.completed = true
	mapScreenAvailableSelections = {}
	for _, nextRoom in ipairs(room.next) do
		table.insert(mapScreenAvailableSelections,nextRoom.x)
	end
	mapScreenX = 0
	currentRoomY = currentRoomY + 1
	mapScreenY = currentRoomY
	if currentRoomY > 1 then
		table.insert(playerPath,currentRoomX)
	end
	mapScreenSelectionMode = true
end

function enterRoom(x)
	mapScreenSelectionMode = false
	currentRoomX = x
	floor = floor + 1

	nextRooms = room.next
	room = nil
	for _, nextRoom in ipairs(nextRooms) do
		if nextRoom.x == currentRoomX then
			room = nextRoom
			break
		end
	end
	if room == nil then
		room = stsMap[currentRoomY][currentRoomX]
	end

	saveGame()
	prepareRoom()
end

function prepareRoom(completed)
	local roomType = room.type
	local rollRandom = makeRand(act.id,room.id,9)
	if roomType == 'event' then
		if completed and completed.eventRoomType ~= nil then
			roomType = completed.eventRoomType
		else
			roomType = generateEventRoomType(rollRandom)
		end
		room.eventType = roomType
	end

	if not completed then
		player:triggerEvent('onEnterRoom',room)
	end

	if roomType == 'monster' then
		roomActionType = 'combat'
		if completed then
			startCombat(monsterEncounters[nextMonsterEncounterIndex - 1],completed)
		else
			startCombat(monsterEncounters[nextMonsterEncounterIndex])
			nextMonsterEncounterIndex = nextMonsterEncounterIndex + 1
		end
	elseif roomType == 'elite' then
		roomActionType = 'combat'
		if completed then
			startCombat(eliteEncounters[nextEliteEncounterIndex - 1],completed)
		else
			startCombat(eliteEncounters[nextEliteEncounterIndex])
			nextEliteEncounterIndex = nextEliteEncounterIndex + 1
		end
	elseif roomType == 'boss' then
		roomActionType = 'combat'
		if completed then
			startCombat(bossEncounters[nextBossEncounterIndex - 1],completed)
		else
			startCombat(bossEncounters[nextBossEncounterIndex],completed)
			nextBossEncounterIndex = nextBossEncounterIndex + 1
		end
	elseif roomType == 'rest' then
		roomActionType = 'event'
		currentEvent = CampfireEvent:new()
		closeChildWindows()
	elseif roomType == 'treasure' then
		roomActionType = 'event'
		currentEvent = TreasureEvent:new()
		closeChildWindows()
	elseif roomType == 'shop' then
		roomActionType = 'event'
		currentEvent = MerchantEvent:new()
		closeChildWindows()
	else
		roomActionType = 'event'
		if completed and completed.eventType ~= nil then
			currentEvent = completed.eventType:new()
		else
			currentEvent = rollEventType(rollRandom):new()
		end
		closeChildWindows()
	end
end

-- main

queueSync(32,1)
startGame(Ironclad,20)
roomActionType = 'combat'
startCombat(TheGuardianEncounter)
addAction(ApplyPowerAction:new(StrengthPower:new(player,20)))
addAction(ApplyPowerAction:new(MetallicizePower:new(player,999)))
